/**
 * Formed from Dust
 * ----------------
 * The Lord forms the man from the dust of the ground and breathes life into his nostrils. Stage: a mound of dark soil under a first sunrise, the figure rising as breath enters; ochre earth, cool morning blue, the first ribs of light over a newborn world.
 *
 * Palette 0x0a0812 → 0x1a1224 · light: constellation · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./adam-kit.js.
 */

import { THREE, createScene, pillar, person } from './adam-kit.js';

const BG = 0x0a0812;
const GROUND = 0x0d1b2a;

export function build(group) {
    const W = createScene(group, { seed: 1568278305, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — constellation */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-30, 70, -150], 10, 0xfff8e8);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-40, 44, -125, 26], [30, 50, -135, 32], [85, 42, -120, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xf0f4f8, { opacity: 0.75 }), [x, y, z], { s: [s, s * 0.22, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x0d1b2a, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x1a1224 });
    W.disc([0, 6, -12], 5, 0x0d0a17, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x0a0812, ry: 0.01, s: 1.01 });
    person(W, group, [4.5, 0, 6], { robe: 0x1a1224, ry: -0.66, s: 1.15 });
    person(W, group, [1, 0, -5], { robe: 0x0d1b2a, ry: -0.33, s: 1.08 });

    return W.finish();
}

export default { build };
